import pyomo.environ as pyo

DATA = {
    "products": ["math", "english"],
    "profit": {"math": 15, "english": 17},
    "min_production": {"math": 40, "english": 60},
    "max_production": {"math": 140, "english": 170},
    "min_total_workbooks": 200,
}


def build_model(data=None):
    d = data or DATA
    products = d["products"]

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=products)

    def production_bounds(m, p):
        return (d["min_production"][p], d["max_production"][p])

    model.production = pyo.Var(
        model.P,
        domain=pyo.NonNegativeIntegers,
        bounds=production_bounds,
    )

    def profit_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(expr=profit_rule, sense=pyo.maximize)

    def total_workbooks_rule(m):
        return sum(m.production[p] for p in m.P) >= d["min_total_workbooks"]

    model.total_workbooks = pyo.Constraint(rule=total_workbooks_rule)

    return model


